const menuToggle=document.querySelector(".menu-toggle");const mainMenu=document.getElementById("main-menu");if(menuToggle){menuToggle.addEventListener("click",(()=>{const isExpanded=menuToggle.getAttribute("aria-expanded")==="true";menuToggle.setAttribute("aria-expanded",!isExpanded);mainMenu.classList.toggle("active")}))}document.querySelectorAll('a[href^="#"]').forEach((anchor=>{anchor.addEventListener("click",(function(e){e.preventDefault();const targetId=this.getAttribute("href");if(targetId==="#")return;const targetElement=document.querySelector(targetId);if(targetElement){if(mainMenu&&mainMenu.classList.contains("active")){mainMenu.classList.remove("active");menuToggle.setAttribute("aria-expanded","false")}targetElement.scrollIntoView({behavior:"smooth",block:"start"})}}))}));const sectionsObserver=new IntersectionObserver((entries=>{entries.forEach((entry=>{if(entry.isIntersecting){entry.target.classList.add("section-visible");sectionsObserver.unobserve(entry.target)}}))}),{threshold:.2,rootMargin:"0px 0px -50px 0px"});document.querySelectorAll(".section-container").forEach((section=>{sectionsObserver.observe(section)}));function createPixelBackground(){const bgElement=document.createElement("div");bgElement.classList.add("pixel-bg-effect");document.body.appendChild(bgElement);for(let i=0;i<20;i++){const pixel=document.createElement("div");pixel.classList.add("floating-pixel");pixel.style.left=`${Math.random()*100}%`;pixel.style.top=`${Math.random()*100}%`;pixel.style.width=`${Math.floor(Math.random()*10)+5}px`;pixel.style.height=pixel.style.width;pixel.style.animationDelay=`${Math.random()*5}s`;bgElement.appendChild(pixel)}}createPixelBackground();const subscribeForm=document.querySelector(".subscribe-form");if(subscribeForm){subscribeForm.addEventListener("submit",(e=>{e.preventDefault();const formElements=subscribeForm.elements;const email=formElements.email.value;const name=formElements.name.value||"brave warrior";const formContainer=subscribeForm.parentElement;formContainer.innerHTML=`\n      <div class="thank-you-message">\n        <h3>Thank you, ${name}!</h3>\n        <p>Your scroll has been received. We'll send ravens to ${email} with news of our quest.</p>\n        <div class="pixel-chest"></div>\n      </div>\n    `}))}function initSubscribeForm(){const form=document.getElementById("subscribe-form");const formResponse=document.getElementById("form-response");if(!form)return;form.addEventListener("submit",(function(e){e.preventDefault();formResponse.innerHTML='<div class="loading-spinner"></div> Sending...';formResponse.className="form-response loading";formResponse.style.display="flex";const formData=new FormData(form);fetch(form.action,{method:"POST",body:formData}).then((response=>{if(!response.ok){throw new Error("Network response was not ok")}return response.json()})).then((data=>{if(data.success){formResponse.className="form-response success";formResponse.textContent=data.message;setTimeout((()=>{const formContainer=form.parentElement;const name=formData.get("name")||"brave warrior";const email=formData.get("email");formContainer.innerHTML=`\n            <div class="thank-you-container">\n              <h3>Thank you, ${name}!</h3>\n              <p>Your scroll has been received. We'll send ravens to ${email} with news of our quest.</p>\n              <div class="pixel-chest"></div>\n            </div>\n          `}),2e3)}else{formResponse.className="form-response error";formResponse.textContent=data.message||"Something went wrong. Please try again."}})).catch((error=>{console.error("Error:",error);formResponse.className="form-response error";formResponse.textContent="Unable to connect to the server. Please try again later."}))}))}initSubscribeForm();function updateCountdown(){const targetDate=new Date("May 30, 2025 00:00:00").getTime();const daysElement=document.querySelector(".count.days");const hoursElement=document.querySelector(".count.hours");const minutesElement=document.querySelector(".count.minutes");const secondsElement=document.querySelector(".count.seconds");if(!daysElement||!hoursElement||!minutesElement||!secondsElement)return;const updateTimer=()=>{const now=(new Date).getTime();const distance=targetDate-now;if(distance<0){daysElement.textContent="00";hoursElement.textContent="00";minutesElement.textContent="00";secondsElement.textContent="00";document.querySelector(".countdown").classList.add("finished");document.querySelector(".countdown").insertAdjacentHTML("afterend",'<p class="launch-message">The quest has begun!</p>');clearInterval(timer);return}const days=Math.floor(distance/(1e3*60*60*24));const hours=Math.floor(distance%(1e3*60*60*24)/(1e3*60*60));const minutes=Math.floor(distance%(1e3*60*60)/(1e3*60));const seconds=Math.floor(distance%(1e3*60)/1e3);daysElement.textContent=days<10?"0"+days:days;hoursElement.textContent=hours<10?"0"+hours:hours;minutesElement.textContent=minutes<10?"0"+minutes:minutes;secondsElement.textContent=seconds<10?"0"+seconds:seconds;secondsElement.classList.add("pulse");setTimeout((()=>{secondsElement.classList.remove("pulse")}),200)};updateTimer();const timer=setInterval(updateTimer,1e3);return timer}updateCountdown();function preloadImages(){const imageUrls=["public/images/pixel-sword.png","public/images/pixel-scroll.png","public/images/sword-icon.png","public/images/scroll-icon.png","public/images/shield-icon.png","public/images/castle-icon.png","public/images/flashcard-icon.png","public/images/achievement-icon.png","public/images/social-icon.png","public/images/theme-icon.png","public/images/Twitter.png","public/images/Instagram.png","public/images/TikTok.png","public/images/Whatsapp.png","public/images/Gmail.png","public/images/Youtube.png"];imageUrls.forEach((url=>{const img=new Image;img.src=url}))}preloadImages();const styleElement=document.createElement("style");styleElement.textContent=`\n  .pixel-bg-effect {\n    position: fixed;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    pointer-events: none;\n    z-index: -1;\n  }\n  \n  .floating-pixel {\n    position: absolute;\n    background-color: var(--accent-color);\n    opacity: 0.3;\n    border-radius: 0;\n    animation: floatPixel 15s linear infinite;\n  }\n  \n  @keyframes floatPixel {\n    0% {\n      transform: translateY(0) rotate(0deg);\n    }\n    50% {\n      transform: translateY(-100px) rotate(180deg);\n    }\n    100% {\n      transform: translateY(0) rotate(360deg);\n    }\n  }\n  \n  .thank-you-message {\n    text-align: center;\n    animation: fadeIn 0.5s ease-in-out;\n  }\n  \n  .pixel-chest {\n    width: 64px;\n    height: 64px;\n    background-image: url('../public/images/treasure-chest.png');\n    background-size: contain;\n    background-repeat: no-repeat;\n    margin: 1rem auto;\n    animation: bounce 2s infinite;\n  }\n  \n  @keyframes fadeIn {\n    from { opacity: 0; }\n    to { opacity: 1; }\n  }\n  \n  @keyframes bounce {\n    0%, 100% { transform: translateY(0); }\n    50% { transform: translateY(-10px); }\n  }\n  \n  .pulse {\n    animation: pulseEffect 0.2s ease-in-out;\n  }\n  \n  @keyframes pulseEffect {\n    0% {\n      transform: scale(1);\n    }\n    50% {\n      transform: scale(1.2);\n    }\n    100% {\n      transform: scale(1);\n    }\n  }\n  \n  /* Update features grid to always be two columns */\n  .features-grid {\n    display: grid;\n    grid-template-columns: repeat(2, 1fr) !important;\n    gap: 1.5rem;\n  }\n  \n  /* Adjust responsiveness for features */\n  @media (max-width: 576px) {\n    .features-grid {\n      grid-template-columns: 1fr !important;\n    }\n  }\n`;document.head.appendChild(styleElement);function initSocialSharing(){const trackShare=platform=>{console.log(`Shared via ${platform}`);const feedbackEl=document.createElement("div");feedbackEl.className="share-feedback";feedbackEl.textContent=`Shared via ${platform}!`;document.body.appendChild(feedbackEl);setTimeout((()=>{feedbackEl.classList.add("fade-out");setTimeout((()=>{document.body.removeChild(feedbackEl)}),500)}),2e3)};document.querySelectorAll(".share-button, .footer-share-link").forEach((btn=>{btn.addEventListener("click",(e=>{const classes=btn.classList;let platform="";if(classes.contains("whatsapp"))platform="WhatsApp";else if(classes.contains("facebook"))platform="Facebook";else if(classes.contains("twitter"))platform="Twitter";else if(classes.contains("email"))platform="Email";else if(classes.contains("tiktok"))platform="TikTok";else if(classes.contains("linkedin"))platform="LinkedIn";else platform=btn.getAttribute("aria-label").replace("Share on ","");if(!classes.contains("email")){trackShare(platform)}}))}));const addCopyLinkButton=()=>{const shareContainer=document.querySelector(".share-buttons");if(!shareContainer)return;const copyButton=document.createElement("a");copyButton.href="#";copyButton.className="share-button copy-link";copyButton.setAttribute("aria-label","Copy link to clipboard");copyButton.innerHTML=`\n      <div class="share-icon copy-icon"></div>\n      <span>Copy Link</span>\n    `;copyButton.addEventListener("click",(e=>{e.preventDefault();navigator.clipboard.writeText(window.location.href).then((()=>{const span=copyButton.querySelector("span");const originalText=span.textContent;span.textContent="Copied!";copyButton.classList.add("copy-success");setTimeout((()=>{span.textContent=originalText;copyButton.classList.remove("copy-success")}),2e3);trackShare("Copy Link")})).catch((err=>{console.error("Could not copy text: ",err);const textArea=document.createElement("textarea");textArea.value=window.location.href;textArea.style.position="fixed";textArea.style.left="-999999px";textArea.style.top="-999999px";document.body.appendChild(textArea);textArea.focus();textArea.select();try{const successful=document.execCommand("copy");const msg=successful?"successful":"unsuccessful";console.log("Fallback: Copying text was "+msg);const span=copyButton.querySelector("span");span.textContent="Copied!";setTimeout((()=>{span.textContent=originalText}),2e3)}catch(err){console.error("Fallback: Could not copy text: ",err)}document.body.removeChild(textArea)}))}));shareContainer.appendChild(copyButton)};addCopyLinkButton();const shareStyles=document.createElement("style");shareStyles.textContent=`\n    .share-feedback {\n      position: fixed;\n      bottom: 20px;\n      left: 50%;\n      transform: translateX(-50%);\n      background-color: var(--accent-color);\n      color: var(--text-dark);\n      font-family: 'Press Start 2P', cursive;\n      font-size: 0.8rem;\n      padding: 10px 20px;\n      border: 3px solid var(--secondary-color);\n      z-index: 100;\n      pointer-events: none;\n      animation: fadeIn 0.5s ease-out;\n    }\n    \n    .share-feedback.fade-out {\n      animation: fadeOut 0.5s ease-in;\n    }\n    \n    .copy-icon {\n      background-image: url('../public/images/link.png');\n    }\n    \n    .copy-success {\n      background-color: #2a623d !important;\n    }\n    \n    @keyframes fadeOut {\n      from { opacity: 1; }\n      to { opacity: 0; }\n    }\n  `;document.head.appendChild(shareStyles)}initSocialSharing();function addDynamicShareMetaTags(){if(document.querySelector('meta[property="og:url"]'))return;const head=document.head;const url=window.location.href;const twitterCard=document.createElement("meta");twitterCard.setAttribute("name","twitter:card");twitterCard.setAttribute("content","summary_large_image");head.appendChild(twitterCard);const twitterTitle=document.createElement("meta");twitterTitle.setAttribute("name","twitter:title");twitterTitle.setAttribute("content","QuizSword - The Ultimate Medieval Quiz Adventure");head.appendChild(twitterTitle);const twitterDesc=document.createElement("meta");twitterDesc.setAttribute("name","twitter:description");twitterDesc.setAttribute("content","Join me in QuizSword, a pixel art medieval quiz game launching on May 30, 2025!");head.appendChild(twitterDesc);const whatsappTitle=document.createElement("meta");whatsappTitle.setAttribute("property","og:site_name");whatsappTitle.setAttribute("content","QuizSword");head.appendChild(whatsappTitle);const canonical=document.createElement("link");canonical.setAttribute("rel","canonical");canonical.setAttribute("href",url);head.appendChild(canonical)}addDynamicShareMetaTags();function initParallaxHeader(){const header=document.querySelector(".parallax-header");const skyLayer=document.querySelector(".sky-layer");const cloudsBackLayer=document.querySelector(".clouds-back-layer");const cloudsFrontLayer=document.querySelector(".clouds-front-layer");if(!header||!skyLayer||!cloudsBackLayer||!cloudsFrontLayer)return;let backCloudPos=0;let frontCloudPos=0;function determineCloudSet(){const urlParams=new URLSearchParams(window.location.search);const skyParam=urlParams.get("sky");if(skyParam==="day"){return"Clouds 1"}else if(skyParam==="afternoon"){return"Clouds 2"}else if(skyParam==="night"){return"Clouds 3"}const currentHour=(new Date).getHours();if(currentHour>=6&&currentHour<=9||currentHour>=19&&currentHour<=21){return"Clouds 2"}else if(currentHour>21||currentHour<6){return"Clouds 3"}else{return"Clouds 1"}}const cloudSet=determineCloudSet();skyLayer.style.backgroundImage=`url('../public/${cloudSet}/1.png')`;cloudsBackLayer.style.backgroundImage=`url('../public/${cloudSet}/2.png')`;cloudsFrontLayer.style.backgroundImage=`url('../public/${cloudSet}/4.png')`;window.addEventListener("scroll",(()=>{const scrollY=window.scrollY;skyLayer.style.transform=`translateY(${scrollY*.1}px) translateZ(-600px) scale(3)`;cloudsBackLayer.style.transform=`translateY(${scrollY*.3}px) translateZ(-300px) scale(2)`;cloudsFrontLayer.style.transform=`translateY(${scrollY*.5}px) translateZ(-100px) scale(1.5)`}));function animateClouds(){backCloudPos-=.2;frontCloudPos-=.5;cloudsBackLayer.style.backgroundPosition=`${backCloudPos}px center`;cloudsFrontLayer.style.backgroundPosition=`${frontCloudPos}px center`;requestAnimationFrame(animateClouds)}animateClouds();console.log(`Using ${cloudSet} based on time: ${(new Date).getHours()}:${(new Date).getMinutes()} or URL parameter`)}initParallaxHeader();function initRockAnimation(){const rockElement=document.getElementById("animated-rock");if(!rockElement)return;let animationSpeed=.8;function updateRockSpeed(speedInSeconds){const clampedSpeed=Math.max(.1,Math.min(3,speedInSeconds));rockElement.style.animationDuration=`${clampedSpeed}s`;console.log(`Rock animation speed set to ${clampedSpeed}s`);return clampedSpeed}function checkSpeedFromURL(){const urlParams=new URLSearchParams(window.location.search);const speedParam=urlParams.get("rockSpeed");if(speedParam&&!isNaN(parseFloat(speedParam))){animationSpeed=updateRockSpeed(parseFloat(speedParam))}}checkSpeedFromURL();window.rockControls={speedUp:function(factor=.8){animationSpeed=updateRockSpeed(animationSpeed*factor);return animationSpeed},slowDown:function(factor=1.25){animationSpeed=updateRockSpeed(animationSpeed*factor);return animationSpeed},setSpeed:function(speedInSeconds){animationSpeed=updateRockSpeed(speedInSeconds);return animationSpeed},getSpeed:function(){return animationSpeed}}}initRockAnimation();